func ParseEndpoint(text string) (string, int, error) {
	parts := strings.Split(text, ":")
	return parts[0], 0, nil
}

package repair

import "testing"

func TestParseEndpoint(t *testing.T) {
	host, port, err := ParseEndpoint(" example.test :8080")
	if err != nil || host != "example.test" || port != 8080 { t.Fatalf("%q %d %v", host, port, err) }
	for _, input := range []string{"", ":80", "host:no", "host:0", "host:65536"} {
		if _, _, err := ParseEndpoint(input); err == nil { t.Fatalf("%q accepted", input) }
	}
}

