import assert from 'node:assert/strict';
import { repair } from './repair.js';

test('chunks without mutation', () => {
  const input = [1, 2, 3, 4, 5];
  assert.deepEqual(repair(input, 2), [[1, 2], [3, 4], [5]]);
  assert.deepEqual(input, [1, 2, 3, 4, 5]);
});
test('rejects invalid size', () => assert.throws(() => repair([1], 0), /size/i));

